// Function to apply 1-stop filter if not already applied
async function ensureMax1Stop(tabId) {
  const snapshot = await browser.snapshot({ tabId });
  const lines = snapshot.text.split('\n');
  const stopsLine = lines.find(l => l.includes('Stops'));
  if (!stopsLine) return;

  if (stopsLine.includes('1 stop or fewer')) {
    // Already applied
    return;
  }

  const m = stopsLine.match(/\[ref=(e\d+)\]/);
  if (!m) return;

  await tool.element_interact({ tabId, ref: m[1], operation: "click", value: null, target_ref: null });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1200 });

  const snap2 = await browser.snapshot({ tabId });
  const radio1Stop = snap2.text.split('\n').find(l => l.includes('1 stop or fewer'));
  if (radio1Stop) {
    const rm = radio1Stop.match(/\[ref=(e\d+)\]/);
    if (rm) {
