const snapshot = await browser.snapshot({ tabId });
const lines = snapshot.text.split('\n');
const stopsLine = lines.find(l => l.includes('Stops'));
console.log("Stops line:", stopsLine);

const match = stopsLine ? stopsLine.match(/\[ref=(e\d+)\]/) : null;
if (match) {
  const ref = match[1];
  await tool.element_interact({ tabId, ref, operation: "click", value: null, target_ref: null });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1500 });

  const snap2 = await browser.snapshot({ tabId });
  const radio1Stop = snap2.text.split('\n').find(l => l.includes('1 stop or fewer'));
  console.log("Radio line:", radio1Stop);
  const rMatch = radio1Stop ? radio1Stop.match(/\[ref=(e\d+)\]/) : null;
  if (rMatch) {
    await tool.element_interact({ tabId, ref: rMatch[1], operation: "click", value: null, target_ref: null });
    await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2000 });
  }
}

const currentUrl = await browserjs(tabId, () => window.location.href);
console.log("URL after 1 stop filter:", currentUrl);

