const tabId = 1675924496;

const parsedFlights = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('li'));
  const results = [];

  for (const item of items) {
    const link = item.querySelector('a') || item.querySelector('[role="link"]') || item.querySelector('button');
    const ariaLabel = item.getAttribute('aria-label') || link?.getAttribute('aria-label') || '';
    const innerText = item.innerText || '';

    // Must be a flight item
    if (!ariaLabel.includes('flight') && (!innerText.includes('$') || !innerText.includes('–'))) continue;

    // Parse ariaLabel if available, e.g.:
    // "From 565 US dollars. 1 stop flight with Alaska and Philippine Airlines. Leaves San Jose Mineta International Airport at 5:24 PM on Tuesday, November 10 and arrives at Ninoy Aquino International Airport at 5:40 AM on Thursday, November 12. Total duration 20 hr 16 min.  Layover (1 of 1) is a 3 hr 27 min layover at Los Angeles International Airport in Los Angeles. Select flight"
    let price = null;
    let airline = null;
    let depTime = null;
    let arrTime = null;
    let depAirport = null;
    let arrAirport = null;
    let duration = null;
    let stops = null;
    let layover = null;

    const priceMatch = ariaLabel.match(/From\s+([\d,]+)\s+US dollars/i) || innerText.match(/\$([\d,]+)/);
    if (priceMatch) price = parseInt(priceMatch[1].replace(/,/g, ''), 10);

    const stopsMatch = ariaLabel.match(/(Nonstop|\d+\s+stop[s]?)\s+flight/i);
    if (stopsMatch) {
      stops = stopsMatch[1];
    } else if (innerText.includes('Nonstop')) {
      stops = 'Nonstop';
    } else if (innerText.match(/\d+\s+stop/i)) {
      stops = innerText.match(/\d+\s+stop[s]?/i)[0];
    }

    const airlineMatch = ariaLabel.match(/flight with ([^.]+)\.\s+Leaves/i);
    if (airlineMatch) {
      airline = airlineMatch[1].trim();
    }

    const leavesMatch = ariaLabel.match(/Leaves\s+(.+?)\s+at\s+([\d:]+\s*[AP]M)\s+on\s+([A-Za-z]+,\s+[A-Za-z]+\s+\d+)\s+and\s+arrives\s+at\s+(.+?)\s+at\s+([\d:]+\s*[AP]M)/i);
    if (leavesMatch) {
      depAirport = leavesMatch[1].trim();
      depTime = leavesMatch[2].trim().replace(/\u202f/g, ' ');
      // arrAirport = leavesMatch[4].trim();
      arrTime = leavesMatch[5].trim().replace(/\u202f/g, ' ');
    }

    const durMatch = ariaLabel.match(/Total duration\s+([^.]+)\./i);
    if (durMatch) duration = durMatch[1].trim();

    const layoverMatch = ariaLabel.match(/Layover\s+\(1 of \d+\)\s+is\s+a\s+([^.]+?)\s+layover\s+at\s+([^.]+)\./i);
    if (layoverMatch) {
      layover = `${layoverMatch[1]} at ${layoverMatch[2]}`;
    } else if (stops === 'Nonstop') {
      layover = 'None (Nonstop)';
    }

    // Fallback parsing from innerText if ariaLabel didn't catch everything
    const lines = innerText.split('\n').map(l => l.trim()).filter(Boolean);
    if (!depTime && lines[0] && lines[0].includes('–')) {
      const parts = lines[0].split('–').map(p => p.trim());
      depTime = parts[0];
      arrTime = parts[1];
    }
    if (!duration) {
      const dLine = lines.find(l => l.includes('hr') || l.includes('min'));
      if (dLine) duration = dLine;
    }
    if (!airline && lines[1] && !lines[1].includes('hr')) {
      airline = lines[1];
    }

    // Parse hour of departure to check evening
    let depHour = null;
    if (depTime) {
      const m = depTime.match(/(\d+):(\d+)\s*([AP]M)/i);
      if (m) {
        let h = parseInt(m[1], 10);
        const ampm = m[3].toUpperCase();
        if (ampm === 'PM' && h !== 12) h += 12;
        if (ampm === 'AM' && h === 12) h = 0;
        depHour = h + parseInt(m[2], 10) / 60;
      }
    }

    results.push({
      price,
      airline,
      depTime,
      arrTime,
      depAirport,
      duration,
      stops,
      layover,
      depHour,
      rawAria: ariaLabel
    });
  }

  return results;
});

console.log(`Parsed ${parsedFlights.length} flights:`);
console.log(JSON.stringify(parsedFlights.slice(0, 4), null, 2));

