{"title":"Run 4 SJC searches and record results","code":"const tabId = 1675924496;

async function ensureMax1Stop(tabId) {
  const snapshot = await browser.snapshot({ tabId });
  const lines = snapshot.text.split('\n');
  const stopsLine = lines.find(l => l.includes('Stops'));
  if (!stopsLine) return;

  if (stopsLine.includes('1 stop or fewer') || stopsLine.includes('1 stop')) {
    return;
  }

  const m = stopsLine.match(/\[ref=(e\d+)\]/);
  if (!m) return;

  await tool.element_interact({ tabId, ref: m[1], operation: "click", value: null, target_ref: null });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1200 });

  const snap2 = await browser.snapshot({ tabId });
  const radio1Stop = snap2.text.split('\n').find(l => l.includes('1 stop or fewer'));
  if (radio1Stop) {
    const rm = radio1Stop.match(/\[ref=(e\d+)\]/);
    if (rm) {
      await tool.element_interact({ tabId, ref: rm[1], operation: "click", value: null, target_ref: null });
      await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1500 });
    }
  }
}

async function parsePageFlights(tabId) {
  return await browserjs(tabId, () => {
    const items = Array.from(document.querySelectorAll('li'));
    const results = [];

    for (const item of items) {
      const link = item.querySelector('a') || item.querySelector('[role="link"]') || item.querySelector('button');
      const ariaLabel = item.getAttribute('aria-label') || link?.getAttribute('aria-label') || '';
      const innerText = item.innerText || '';

      if (!ariaLabel.includes('flight') && (!innerText.includes('$') || !innerText.includes('–'))) continue;

      let price = null;
      let airline = null;
      let depTime = null;
      let arrTime = null;
      let depAirport = null;
      let duration = null;
      let stops = null;
      let layover = null;

      const priceMatch = ariaLabel.match(/From\s+([\d,]+)\s+US dollars/i) || innerText.match(/\$([\d,]+)/);
      if (priceMatch) price = parseInt(priceMatch[1].replace(/,/g, ''), 10);

      const stopsMatch = ariaLabel.match(/(Nonstop|\d+\s+stop[s]?)\s+flight/i);
      if (stopsMatch) {
        stops = stopsMatch[1];
      } else if (innerText.includes('Nonstop')) {
        stops = 'Nonstop';
      } else if (innerText.match(/\d+\s+stop/i)) {
        stops = innerText.match(/\d+\s+stop[s]?/i)[0];
      }

      const airlineMatch = ariaLabel.match(/flight with ([^.]+)\.\s+Leaves/i);
      if (airlineMatch) {
        airline = airlineMatch[1].trim();
      }

      const leavesMatch = ariaLabel.match(/Leaves\s+(.+?)\s+at\s+([\d:]+\s*[AP]M)\s+on\s+([A-Za-z]+,\s+[A-Za-z]+\s+\d+)\s+and\s+arrives\s+at\s+(.+?)\s+at\s+([\d:]+\s*[AP]M)/i);
      if (leavesMatch) {
        depAirport = leavesMatch[1].trim();
        depTime = leavesMatch[2].trim().replace(/\u202f/g, ' ');
        arrTime = leavesMatch[5].trim().replace(/\u202f/g, ' ');
      }

      const durMatch = ariaLabel.match(/Total duration\s+([^.]+)\./i);
      if (durMatch) duration = durMatch[1].trim();

      const layoverMatch = ariaLabel.match(/Layover\s+\(1 of \d+\)\s+is\s+a\s+([^.]+?)\s+layover\s+at\s+([^.]+)\./i);
      if (layoverMatch) {
        layover = `${layoverMatch[1]} at ${layoverMatch[2]}`;
      } else if (stops === 'Nonstop') {
        layover = 'None (Nonstop)';
      }

      const lines = innerText.split('\n').map(l => l.trim()).filter(Boolean);
      if (!depTime && lines[0] && lines[0].includes('–')) {
        const parts = lines[0].split('–').map(p => p.trim());
        depTime = parts[0];
        arrTime = parts[1];
      }
      if (!duration) {
        const dLine = lines.find(l => l.includes('hr') || l.includes('min'));
        if (dLine) duration = dLine;
      }
      if (!airline && lines[1] && !lines[1].includes('hr')) {
        airline = lines[1];
      }

      let depHour = null;
      if (depTime) {
        const m = depTime.match(/(\d+):(\d+)\s*([AP]M)/i);
        if (m) {
          let h = parseInt(m[1], 10);
          const ampm = m[3].toUpperCase();
          if (ampm === 'PM' && h !== 12) h += 12;
          if (ampm === 'AM' && h === 12) h = 0;
          depHour = h + parseInt(m[2], 10) / 60;
        }
      }

      results.push({
        price,
        airline,
        depTime,
        arrTime,
        depAirport,
        duration,
        stops,
        layover,
        depHour,
        rawAria: ariaLabel
      });
    }

    return results;
  });
}

const dates = ["2026-11-10", "2026-11-11", "2026-11-12", "2026-11-13"];
const sjcResults = {};

for (const date of dates) {
  console.log(`Searching SJC on ${date}...`);
  await tool.navigate({
    tabId,
    url: `https://www.google.com/travel/flights?q=Flights%20to%20MNL%20from%20SJC%20on%20${date}%20one%20way`
  });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2500 });
  await ensureMax1Stop(tabId);
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1500 });

  const flights = await parsePageFlights(tabId);
  // Evening: depHour >= 17 (5:00 PM)
  const eveningFlights = flights.filter(f => (f.stops === 'Nonstop' || f.stops === '1 stop') && f.depHour !== null && f.depHour >= 17.0);

  eveningFlights.sort((a, b) => (a.price || 99999) - (b.price || 99999));

  sjcResults[date] = {
    totalFlights: flights.length,
    eveningCount: eveningFlights.length,
    cheapestEvening: eveningFlights[0] || null,
    allEvening: eveningFlights,
    allFlights: flights
  };
  console.log(`SJC ${date}: found ${eveningFlights.length} evening 1-stop flights. Cheapest:`, 
    eveningFlights[0] ? `$${eveningFlights[0].price} with ${eveningFlights[0].airline} (${eveningFlights[0].depTime}, ${eveningFlights[0].duration}, ${eveningFlights[0].layover})` : "None");
}

await write("tmp://sjc_results.json", JSON.stringify(sjcResults, null, 2));
