// Let's check China Airlines baggage rules in tab 1675924585
const tabId = 1675924585;

await tool.navigate({
  tabId,
  url: "https://www.china-airlines.com/us/en/fly/prepare-for-the-flight/baggage/baggage-rules"
});

await tool.wait_for({ tabId, condition: "load_state", value: "load" });
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });

const text = await browserjs(tabId, () => document.body.innerText);
console.log("CI Baggage Rules length:", text.length);

// Search for pieces, weight, USA, transpacific
const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
const snippets = [];
for (let i = 0; i < lines.length; i++) {
  const l = lines[i];
  if (l.includes('23 kg') || l.includes('50 lb') || l.includes('Economy') || l.includes('Carry-on') || l.includes('Checked Baggage') || l.includes('Piece')) {
    snippets.push(lines.slice(Math.max(0, i-1), Math.min(lines.length, i+4)).join('\n'));
    i += 3;
  }
}

console.log("CI Baggage snippets:\n" + snippets.slice(0, 10).join('\n---\n'));

